const targets = await (await fetch('http://127.0.0.1:9222/json')).json();
const target = targets.find((t) => t.type === 'page');
if (!target) throw new Error('No Chrome page target');
const ws = new WebSocket(target.webSocketDebuggerUrl);
await new Promise((resolve, reject) => { ws.onopen = resolve; ws.onerror = reject; });
let nextId = 0;
const pending = new Map();
ws.onmessage = ({ data }) => { const msg = JSON.parse(data); if (msg.id && pending.has(msg.id)) { pending.get(msg.id)(msg); pending.delete(msg.id); } };
function send(method, params = {}) { return new Promise((resolve) => { const id = ++nextId; pending.set(id, resolve); ws.send(JSON.stringify({ id, method, params })); }); }
async function ev(expression) {
  const r = await send('Runtime.evaluate', { expression, returnByValue: true, awaitPromise: true });
  if (r.result.exceptionDetails) throw new Error(r.result.exceptionDetails.exception?.description || r.result.exceptionDetails.text);
  return r.result.result.value;
}
await send('Page.enable'); await send('Runtime.enable'); await send('Page.navigate', {url:'http://127.0.0.1:8765/index.html'});
for(let i=0;i<100;i++){ try { if(await ev("document.readyState==='complete' && !!document.querySelector('#begin')")) break; }catch{} await new Promise(r=>setTimeout(r,100)); }
await ev("document.querySelector('#begin').click(); for(let i=0;i<40;i++) document.querySelector('#storyNext').click(); true");
await ev("for(let i=0;i<12;i++) document.querySelector('#dialogue').dispatchEvent(new PointerEvent('pointerdown',{bubbles:true})); true");
await ev("new Promise(r=>setTimeout(r,100))");
const before = await ev("({hud: getComputedStyle(document.querySelector('#hud')).display, grappleVisible:grappleGun.visible, trophies:document.querySelector('#trophyCount').textContent, objective:document.querySelector('#objectiveTitle').textContent, beat:document.querySelector('#storyProgress').textContent})");
async function collect(id){
  const placed=await ev(`(()=>{const it=items.find(i=>i.id==='${id}');player.position.set(it.pos.x,0,it.pos.z);return true})()`);
  await ev("new Promise(r=>setTimeout(r,100))");
  const targetName=await ev("interactTarget?.id || null");
  await ev("window.dispatchEvent(new KeyboardEvent('keydown',{key:'e',bubbles:true}));true");
  const done=await ev(`items.find(i=>i.id==='${id}').done`);
  const extra=await ev("({dialogueBusy, grappleVisible:grappleGun.visible, trophyCount:document.querySelector('#trophyCount').textContent, objective:document.querySelector('#objectiveTitle').textContent})");
  await ev("for(let i=0;i<8;i++) document.querySelector('#dialogue').dispatchEvent(new PointerEvent('pointerdown',{bubbles:true}));true");
  return {id,targetName,done,...extra};
}
const gear=[];
for(const id of ['book','batarang','smoke','grapple','suit','car']) gear.push(await collect(id));
const trophy1=await collect('trophy1');
const trophy2=await collect('trophy2');
const trophyState=await ev("({counter:document.querySelector('#trophyCount').textContent, remaining:items.filter(i=>i.id.startsWith('trophy')&&!i.done).length})");
const lift=await collect('lift');
const after=await ev("({combat, combatHud:document.querySelector('#combatHud').classList.contains('show'), trophyCounter:document.querySelector('#trophyCount').textContent, remainingTrophies:items.filter(i=>i.id.startsWith('trophy')&&!i.done).length, grappleVisible:grappleGun.visible, liftDone:items.find(i=>i.id==='lift').done})");
console.log(JSON.stringify({before,gear,trophy1,trophy2,trophyState,lift,after},null,2));
ws.close();

