126: function fireGrapple(){if(!combat||dialogueBusy||grappleCooldown>0)return;grappleCooldown=2.2;const target=activeEnemy();if(!target){showToast('NO GRAPPLE TARGET');return}const toTarget=new THREE.Vector3(target.group.position.x-player.position.x,0,target.group.position.z-player.position.z),distance=toTarget.length();if(distance>14){showToast('OUT OF GRAPPLE RANGE');return}const direction=toTarget.normalize();player.position.x=target.group.position.x-direction.x*1.35;player.position.z=target.group.position.z-direction.z*1.35;player.rotation.y=Math.atan2(direction.x,-direction.z);target.group.position.addScaledVector(direction,-.25);hitEnemy(target,1,1.5);showToast('GRAPPLE — CLOSING IN')}
