200: function updateObjective(){const remaining=items.filter(i=>i.id!=='lift'&&!i.id.startsWith('trophy')&&!i.done);if(remaining.length){$('#objectiveTitle').textContent=remaining.length===6?'Explore the cave':'Equip the mission';$('#objectiveText').textContent=remaining.length===6?'Find the equipment Alfred left for you.':`${remaining.length} ${remaining.length===1?'piece':'pieces'} of gear remain. Follow the markers.`;}else{$('#objectiveTitle').textContent='Take the elevator';$('#objectiveText').textContent='All equipment checked. Head to the lift when you are ready.'}}
