208: function startDialogue(lines){dialogueQueue=lines.map(([s,t])=>({s,t}));dialogueBusy=true;$('#dialogue').classList.add('show');nextLine()}
209: function nextLine(){if(!dialogueQueue.length){dialogueBusy=false;$('#dialogue').classList.remove('show');return}let d=dialogueQueue.shift();$('#speaker').textContent=d.s;$('#line').textContent='“'+d.t+'”'}
