194: function strike(){if(!combat||dialogueBusy||attackCooldown>0)return;attackCooldown=.48;const target=activeEnemy();if(!target){showToast('NO ACTIVE THREAT');return}const d=new THREE.Vector3(target.group.position.x-player.position.x,0,target.group.position.z-player.position.z),distance=d.length(),forward=new THREE.Vector3(Math.sin(player.rotation.y),0,-Math.cos(player.rotation.y));if(distance<2.5&&(distance<.85||forward.dot(d.normalize())>.15)){const push=new THREE.Vector3(target.group.position.x-player.position.x,0,target.group.position.z-player.position.z).normalize();target.group.position.addScaledVector(push,.55);target.group.rotation.y=Math.atan2(push.x,-push.z);hitEnemy(target,1,.65)}else showToast('CLOSE THE DISTANCE')}
195: function throwBatarang(){if(!combat||dialogueBusy||batarangCooldown>0)return;if(batarangs<=0){showToast('NO BATARANGS LEFT');return}batarangs--;batarangCooldown=.55;const target=activeEnemy();if(target){const d=new THREE.Vector3(target.group.position.x-player.position.x,0,target.group.position.z-player.position.z),distance=d.length(),forward=new THREE.Vector3(Math.sin(player.rotation.y),0,-Math.cos(player.rotation.y));if(distance<13&&forward.dot(d.normalize())>.05){hitEnemy(target,1,1.35);showToast(target.dead?'BATARANG — THREAT DOWN':'BATARANG HIT')}else showToast('BATARANG MISSED — FACE YOUR TARGET')}else showToast('NO ACTIVE TARGET');updateToolTip()}
196: function fireGrapple(){if(!combat||dialogueBusy||grappleCooldown>0)return;grappleCooldown=2.2;const target=activeEnemy();if(!target){showToast('NO GRAPPLE TARGET');return}const toTarget=new THREE.Vector3(target.group.position.x-player.position.x,0,target.group.position.z-player.position.z),distance=toTarget.length();if(distance>14){showToast('OUT OF GRAPPLE RANGE');return}const direction=toTarget.normalize();player.position.x=target.group.position.x-direction.x*1.35;player.position.z=target.group.position.z-direction.z*1.35;player.rotation.y=Math.atan2(direction.x,-direction.z);target.group.position.addScaledVector(direction,-.25);hitEnemy(target,1,1.5);showToast('GRAPPLE — CLOSING IN')}
197: function deploySmoke(){if(!combat||dialogueBusy||smokeCooldown>0)return;if(smokePellets<=0){showToast('NO SMOKE PELLETS LEFT');return}smokePellets--;smokeCooldown=8;smokeTimer=3.2;if(!smokeCloud){smokeCloud=new THREE.Mesh(new THREE.SphereGeometry(1,16,12),new THREE.MeshBasicMaterial({color:0x89919a,transparent:true,opacity:.22,depthWrite:false}));smokeCloud.scale.set(2.8,1.8,2.8);street.add(smokeCloud)}smokeCloud.visible=true;smokeCloud.position.set(player.position.x,1.25,player.position.z);const target=activeEnemy();if(target){const distance=Math.hypot(target.group.position.x-player.position.x,target.group.position.z-player.position.z);if(distance<5.5)target.stun=Math.max(target.stun,2.8)}showToast('SMOKE SCREEN — THEY CAN’T SEE YOU');updateToolTip()}
