240: function deploySmoke(){if(!combat||dialogueBusy||smokeCooldown>0)return;if(smokePellets<=0){showToast('NO SMOKE PELLETS LEFT');return}smokePellets--;smokeCooldown=8;smokeTimer=3.2;if(!smokeCloud){smokeCloud=new THREE.Mesh(new THREE.SphereGeometry(1,16,12),new THREE.MeshBasicMaterial({color:0x89919a,transparent:true,opacity:.22,depthWrite:false}));smokeCloud.scale.set(2.8,1.8,2.8);street.add(smokeCloud)}smokeCloud.visible=true;smokeCloud.position.set(player.position.x,1.25,player.position.z);const target=activeEnemy();if(target){const distance=Math.hypot(target.group.position.x-player.position.x,target.group.position.z-player.position.z);if(distance<5.5)target.stun=Math.max(target.stun,2.8)}showToast('SMOKE SCREEN — THEY CAN’T SEE YOU');updateToolTip()}
241: function updateToolTip(){if(!combat)return;$('#fightTip').textContent='F HIT · Q BATA '+batarangs+' · G GRAPPLE · C SMOKE '+smokePellets+' · R GUARD · SHIFT DODGE'}
242: function showToast(t){$('#toast').textContent=t;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').textContent=combat?'GOTHAM IS STILL WATCHING':'THE CAVE IS YOURS TO SHAPE',3200)}
243: function updateObjective(){const remaining=items.filter(i=>i.id!=='lift'&&!i.id.startsWith('trophy')&&!i.done);if(remaining.length){$('#objectiveTitle').textContent=remaining.length===6?'Explore the cave':'Equip the mission';$('#objectiveText').textContent=remaining.length===6?'Find the equipment Alfred left for you.':`${remaining.length} ${remaining.length===1?'piece':'pieces'} of gear remain. Follow the markers.`;}else{$('#objectiveTitle').textContent='Take the elevator';$('#objectiveText').textContent='All equipment checked. Head to the lift when you are ready.'}}
